styles.css:
position: relative;
overflow: hidden;
align-items: center;
max-inline-size: 24.167rem;
text-align: center;
transform-origin: top center;
--ls-card-services-border-active: var(--wp--custom--color--link--accent);
--ls-card-services-icon-border-active: var(--wp--custom--color--icon--background);
--ls-card-services-shadow-active: var(--wp--custom--shadow--card--hover);
--ls-card-services-icon-shadow-active: var(--wp--custom--shadow--elevation--300), 0 22px 44px -22px color-mix(in srgb, var(--wp--custom--color--icon--background) 76%, transparent);
--ls-card-services-scale: 1.05;
--ls-card-services-accent-thickness: 8px;
--ls-link-arrow-offset: 0;
--ls-accent-gradient-image: linear-gradient(90deg, var(--wp--custom--color--effect--spotlight--secondary) 0%, var(--wp--custom--color--effect--spotlight--primary) 50%, var(--wp--custom--color--effect--spotlight--secondary) 100%);
--ls-accent-gradient-size: 200% auto;
--ls-accent-gradient-start-position: 0%;
--ls-accent-gradient-end-position: 100%;
--ls-accent-gradient-duration: var(--wp--custom--animation--duration--loop);
--ls-accent-gradient-delay: var(--wp--custom--animation--delay--none);
--ls-accent-gradient-timing: var(--wp--custom--animation--easing--smooth);
--ls-accent-gradient-direction: alternate;
--ls-accent-gradient-reduced-position: 100%;

& .ls-card__icon-shell {
	align-self: center;
}

& .ls-card-services__content {
	display: flex;
	flex: 1 1 auto;
	flex-direction: column;
	align-items: center;
	gap: var(--wp--preset--spacing--20);
	inline-size: 100%;
}

& .ls-card-services__content > * {
	margin-block: 0;
}

& .ls-card-services__list {
	inline-size: 100%;
	margin-block: 0;
}

& .ls-card-services__cta {
	position: static;
	margin-top: auto;
	margin-bottom: 0;
}

& .ls-card-services__cta a::before {
	content: "";
	position: absolute;
	inset: 0;
	z-index: 1;
}

&::before {
	content: "";
	position: absolute;
	inset-block-start: 0;
	inset-inline: 0;
	block-size: var(--ls-card-services-accent-thickness);
	background-image: var(--ls-accent-gradient-image);
	background-position: var(--ls-accent-gradient-start-position) center;
	background-repeat: no-repeat;
	background-size: var(--ls-accent-gradient-size);
	z-index: var(--wp--custom--z-index--base);
}

& > * {
	position: relative;
	z-index: var(--wp--custom--z-index--content);
}
